heroArtwork.src='banaras-boat-lit.png';heroArtwork.alt='Dhiraj and Neha seen from behind in a boat surrounded by floating diyas on the Ganga';
let boatComplete=false,boatStarted=false;const revealTimer=new MutationObserver(()=>{if(entry.classList.contains('names-ready')&&!boatComplete){entry.classList.remove('names-ready');entry.classList.add('boat-ready');entry.querySelector('.boat-light-control').focus()}});revealTimer.observe(entry,{attributes:true,attributeFilter:['class']});
const boatLight=document.createElement('button');boatLight.className='boat-light-control';boatLight.textContent='Tap to light the floating diyas';entry.append(boatLight);
[[25,12,0],[72,13,.6],[50,23,1.2],[80,26,1.7]].forEach(([x,y,d])=>{const burst=document.createElement('div');burst.className='boat-burst';burst.style.cssText=`--x:${x}%;--y:${y}%;--delay:${d}s`;burst.innerHTML='<img src="golden-firework.svg" alt="">';entry.append(burst)});
boatLight.onclick=()=>{if(boatStarted)return;boatStarted=true;entry.classList.add('boat-lit');setTimeout(()=>entry.classList.add('boat-celebrating'),motion?50:6200);setTimeout(()=>{boatComplete=true;entry.classList.add('names-ready');entry.querySelector('.banaras-continue').focus()},motion?100:10500)};
// Blend tiny local regions around the floating lamps, never a sweeping image edge.
const boatBackdrop=entry.querySelector('.banaras-reveal');const ambient=document.createElement('div');ambient.className='boat-ambient-light';boatBackdrop.append(ambient);
const waterLamps=[[2,93],[96,96],[3,68],[98,68],[5,63],[96,63],[6,58],[93,58],[3,54],[96,54],[8,51],[91,51],[14,49],[85,49],[20,47],[79,47],[8,46],[92,46],[17,45],[83,45],[26,45],[74,45],[5,44],[95,44],[14,43],[86,43],[24,43],[76,43],[31,44],[68,44],[9,42],[90,42],[19,42],[80,42],[29,42],[70,42],[38,43],[61,43]];
const localLampEffects=waterLamps.map(([x,y],i)=>{const patch=document.createElement('div');patch.className='boat-lamp-patch';const spark=document.createElement('span');spark.className='boat-spark';const position=()=>{const r=boatBackdrop.getBoundingClientRect(),s=Math.max(r.width/941,r.height/1672),iw=941*s,ih=1672*s,px=(r.width-iw)/2+x/100*iw,py=(r.height-ih)/2+y/100*ih;const radius=y>60?32:y>47?20:12;patch.style.maskImage=`radial-gradient(ellipse ${radius}px ${radius*1.7}px at ${px}px ${py}px,#000 15%,transparent 100%)`;patch.style.webkitMaskImage=patch.style.maskImage;spark.style.left=px+'px';spark.style.top=py+'px';const size=y>60?3:y>47?2:1.2;spark.style.width=size+'px';spark.style.height=size*2+'px'};position();addEventListener('resize',position);boatBackdrop.append(spark);return {patch,spark}});
boatLight.onclick=()=>{if(boatStarted)return;boatStarted=true;entry.classList.add('boat-lit');localLampEffects.forEach(({patch,spark},i)=>setTimeout(()=>{patch.classList.add('glowing');spark.classList.add('glowing')},motion?0:120+i*135));setTimeout(()=>entry.classList.add('boat-celebrating'),motion?50:7500);setTimeout(()=>{boatComplete=true;entry.classList.add('names-ready');entry.querySelector('.banaras-continue').focus()},motion?100:11800)};
// Remove lamp overlays near the couple's silhouettes, including necks and shoulders.
waterLamps.forEach(([x,y],i)=>{if((x>22&&x<81&&y>=38)||(x>15&&x<87&&y>=47)){localLampEffects[i].patch.remove();localLampEffects[i].spark.remove()}});
entry.querySelectorAll('.boat-burst').forEach((burst,i)=>{burst.style.setProperty('--safe-sky-y',[9,12,20,18][i]+'%')});
const boatStars=document.createElement('div');boatStars.className='boat-stars';boatStars.setAttribute('aria-hidden','true');for(let i=0;i<48;i++){const star=document.createElement('span');star.className='boat-moving-star';star.style.cssText=`left:${Math.random()*96}%;top:${Math.random()*90}%;--duration:${7+Math.random()*10}s;--delay:${-Math.random()*15}s;width:${i%5===0?3:2}px;height:${i%5===0?3:2}px`;boatStars.append(star)}entry.querySelector('.banaras-reveal').append(boatStars);
boatStars.remove();const clouds=document.createElement('div');clouds.className='boat-clouds';clouds.setAttribute('aria-hidden','true');clouds.innerHTML='<div class="boat-cloud"></div><div class="boat-cloud"></div>';entry.querySelector('.banaras-reveal').append(clouds);
const riverRipples=document.createElement('div');riverRipples.className='river-ripples';riverRipples.setAttribute('aria-hidden','true');entry.querySelector('.banaras-reveal').append(riverRipples);
// Let the doors finish their motion before presenting the diya prompt.
const boatPromptTransition=new MutationObserver(()=>{if(entry.classList.contains('boat-ready')&&!entry.dataset.promptSettled){entry.dataset.promptSettled='true';boatLight.style.opacity='0';boatLight.style.pointerEvents='none';setTimeout(()=>{boatLight.style.opacity='';boatLight.style.pointerEvents=''},motion?0:1100);boatPromptTransition.disconnect()}});boatPromptTransition.observe(entry,{attributes:true,attributeFilter:['class']});
// Continue into a dedicated invitation page.
entry.querySelector('.banaras-continue').onclick=()=>{entry.style.transition='opacity .55s';entry.style.opacity='0';setTimeout(()=>location.assign('invitation.html'),motion?0:500)};

